/**
 * What a Roblox instance holds.
 *
 * Generated by `scripts/build-properties.mjs` from Roblox's own documentation
 * repository — do not edit by hand. Properties a game script cannot read are not
 * here: anything behind a security context, anything the engine marks
 * `NotScriptable`, and anything deprecated.
 *
 * **Each class lists only what it declares itself.** Inherited properties are
 * not copied down — that would write `BasePart`'s two hundred lines into every
 * class derived from it. Call `propertiesOf` below, which walks the inheritance
 * chain, rather than reading `CLASS_PROPERTIES` directly.
 *
 * **No summaries.** Every property documents one and they were two thirds of
 * this file; nothing in the editor shows them, and a tablet downloads this. Run
 * `npm run build:properties -- --summaries` to put them back.
 *
 * Like every other generated list this is a **suggestion rather than a gate**:
 * the property name is a dropdown you can type past, so a property newer than
 * this build still compiles.
 */

import { CLASS_PARENTS } from "./robloxData.js";

