/**
 * The walk is the same answer every time and a picker asks for it per keystroke,
 * so each class is resolved once.
 */
const resolved = new Map<string, readonly ClassProperty[]>();

/**
 * Every property `className` has, its own first and its ancestors' after.
 *
 * Nearest class first, which is what makes an override win: `BasePart.Color`
 * is reached before `Instance` is looked at, and a name already taken is
 * skipped rather than listed twice.
 *
 * A class the catalogue has never heard of gives `[]` rather than throwing.
 * Every pin that offers this list also takes a name typed by hand, so a class
 * newer than this build is a thinner menu and not an error.
 */
export function propertiesOf(className: string): readonly ClassProperty[] {
	const cached = resolved.get(className);
	if (cached) return cached;

	const out: ClassProperty[] = [];
	const seen = new Set<string>();
	// `walked` rather than a depth limit: a chain that loops is the generated
	// data's problem to survive rather than a hang in the editor.
	const walked = new Set<string>();
	let current: string | undefined = className;
	while (current !== undefined && !walked.has(current)) {
		walked.add(current);
		for (const property of CLASS_PROPERTIES[current] ?? []) {
			if (seen.has(property.name)) continue;
			seen.add(property.name);
			out.push(property);
		}
		current = CLASS_PARENTS[current];
	}

	resolved.set(className, out);
	return out;
}
